@sealed
class AccountImpl extends RustOpaque implements Account {
  // Not to be used by end users
  AccountImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  AccountImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        ScaasSdk.instance.api.rust_arc_increment_strong_count_Account,
    rustArcDecrementStrongCount:
        ScaasSdk.instance.api.rust_arc_decrement_strong_count_Account,
    rustArcDecrementStrongCountPtr:
        ScaasSdk.instance.api.rust_arc_decrement_strong_count_AccountPtr,
  );

  /// The rows of seed `seed`, in order.
  Future<List<AccountInfo>> accounts({required String seed}) => ScaasSdk
      .instance
      .api
      .scaasSdkAccountAccountAccounts(that: this, seed: seed);

  /// Adds the native key of `network` at `index` (the address `scaas-ua` derives, as clientkeys `describe` prints it).
  /// `Argument`: an unknown network, a network without an address here (`ton`, `hedera_ed25519`); `AccountExists`:
  /// the same key twice.
  Future<AccountInfo> addNative({required AddNative req}) => ScaasSdk
      .instance
      .api
      .scaasSdkAccountAccountAddNative(that: this, req: req);

  /// Adds the UA key `kind` of wallet `account` at `index` to seed `seed` (unlocked: `WalletLocked`), its UA the one
  /// `scaas-ua` derives; the MAC rewritten. `Argument`: an EIP-2333 kind at an index other than 0 (CLI-UAL-15, `scaas-ua`'s
  /// rule), a kind with no UA of its own, a name empty, above 64 bytes or with a control or format (`Cf`, bidi) character;
  /// `AccountExists`: the same key twice.
  Future<AccountInfo> addUa({required AddUa req}) =>
      ScaasSdk.instance.api.scaasSdkAccountAccountAddUa(that: this, req: req);

  /// Adds a watch row: an id, no key; nothing is ever signed for it ([`Account::signs`]).
  Future<AccountInfo> addWatch({required AddWatch req}) => ScaasSdk.instance.api
      .scaasSdkAccountAccountAddWatch(that: this, req: req);

  /// A new passkey (spec §7 "Passkey keys"; owner 2026-11-19, S1): the `Authenticator` creates it on the deployment's RP ID
  /// (the seed's other passkeys excluded), its `webauthn-p256` (0x0100) key data and credential id stored as a key row of
  /// `seed` (unlocked: `WalletLocked`), the UA `scaas-ua` derives; the `KeyRef` that signs with it. `AuthenticatorRefused`: no
  /// authenticator or RP ID, a refusal; `Argument`: a bad name or key data.
  Future<KeyRef> createPasskeyKey({required CreatePasskeyKey req}) => ScaasSdk
      .instance
      .api
      .scaasSdkAccountAccountCreatePasskeyKey(that: this, req: req);

  /// A new secure-element P-256 key (spec §7 "Secure-element keys"; S1): the `Authenticator` generates it under `policy`, its
  /// `p256` (0x0101) key data and handle stored as a key row of `seed` (unlocked); the `KeyRef` that signs with it (MESSAGE
  /// mode). Not recoverable without a second member or a guardian: the app says so. Errors as [`Account::create_passkey_key`].
  Future<KeyRef> createSeKey({required CreateSeKey req}) => ScaasSdk
      .instance
      .api
      .scaasSdkAccountAccountCreateSeKey(that: this, req: req);

  /// The rows of seed `seed`, each EVM native row marked when its code on chain `chain` is an EIP-7702 designator
  /// (`0xef0100 ‖ address`, CLI-SGN-40 rule 3): shown with the mark and warned; the SDK builds no type-4 transaction, so it
  /// offers no clearing (CLI-SDK-31).
  Future<List<AccountInfo>> marks({
    required String seed,
    required String chain,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountMarks(
    that: this,
    seed: seed,
    chain: chain,
  );

  /// The `msig` `ua` (`0x` + 64 hex) on `chain`'s registry: its first and current structures, each slot enabled and accepted
  /// apart, its update counter, whether it can authorize (CTR-UA-37). `Argument`: no `msig` of that id there.
  Future<MsigState> msigState({required String chain, required String ua}) =>
      ScaasSdk.instance.api.scaasSdkAccountAccountMsigState(
        that: this,
        chain: chain,
        ua: ua,
      );

  /// The account index a new wallet of seed `seed` takes: one past the highest a UA row uses (0 for none). One index per
  /// wallet, for every attribute it registers (CLI-SDK-07).
  Future<int> nextAccount({required String seed}) => ScaasSdk.instance.api
      .scaasSdkAccountAccountNextAccount(that: this, seed: seed);

  /// The PQZ decoy candidates of chain `chain`'s token registry (the profile's; owner P19): the `0x0142` lists of every
  /// enabling generation on its walk, concatenated, distinct by key hash ([`crate::line`]). The draw itself is `scaas-ua`'s
  /// `pickDecoys` over these.
  Future<List<String>> pqzDecoyCandidates({required String chain}) => ScaasSdk
      .instance
      .api
      .scaasSdkAccountAccountPqzDecoyCandidates(that: this, chain: chain);

  /// `acceptMembership(ua, memberSig)` of `req.slot` (CTR-UA-37), signed over typed `UAMembership{ua, member}` by
  /// `scaas-ua` (`membership_sig_current`, the current structure: an appended slot accepts too); landed when the slot's
  /// accepted bit is set. `None`: the slot accepted already.
  Future<ArcRegistryWrite?> prepareAcceptMembership({
    required AcceptMembership req,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareAcceptMembership(
    that: this,
    req: req,
  );

  /// `completeRecovery(new_key)` on `account` (CTR-ACC-03): anyone's call once `RECOVERY_DELAY` (two days) has passed since
  /// the guardian's `initiateRecovery(new_key)`; a native send of `key` quoted for review (before the delay its simulation
  /// reverts and the quote fails).
  Future<NativeQuote> prepareCompleteRecovery({
    required KeyRef key,
    required String chain,
    required String account,
    required SubjectKeyArgs newKey,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareCompleteRecovery(
    that: this,
    key: key,
    chain: chain,
    account: account,
    newKey: newKey,
  );

  /// The guardian's recovery of `account` (CTR-ACC-03): `op` names the guardian `SmartKeyAccount` and its key; its `Execute`
  /// of the decoded `initiateRecovery(new_key)` on `account`. `completeRecovery(new_key)` may follow after `RECOVERY_DELAY`
  /// (two days), by anyone; the account's own `CancelRecovery` stops it.
  Future<ArcPrepared> prepareInitiateRecovery({
    required SmartOp op,
    required String account,
    required SubjectKeyArgs newKey,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareInitiateRecovery(
    that: this,
    op: op,
    account: account,
    newKey: newKey,
  );

  /// The KEM repair (CTR-UA-07, `scaas-ua` `kem_repair`): after a registration in the hash-commit form, or one landed by
  /// someone else in that form, the `setKemKey(ua, 0, kem, UASig())` that stores `key`'s KEM key (version 0) when the commit
  /// is unfilled; `None` when nothing is to repair (no commit, or filled). `WalletLocked`; `Argument` as `prepare_register`.
  Future<ArcRegistryWrite?> prepareKemRepair({
    required KeyRef key,
    required String chain,
    required KeyRef payer,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareKemRepair(
    that: this,
    key: key,
    chain: chain,
    payer: payer,
  );

  /// `registerMsig` of `req.structure` (spec §7): its `pop` by `req.slots` over the registration digest (`pop` v2; a native
  /// member's slot is not built here: `Argument`), the arguments by `scaas-ua` (`registration_args`), skipped when the UA is
  /// registered. An `msig` member must be registered first (its structures are read).
  Future<List<ArcRegistryWrite>> prepareMsigRegister({
    required MsigRegister req,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareMsigRegister(
    that: this,
    req: req,
  );

  /// Prepares the registration of `req.key` (spec §7): the arguments and the PoP by `scaas-ua`, then the writes (the
  /// registration, `storePqzPop` when split, `setKemKey` for a hash-committed KEM key), in the order they must land; an
  /// already registered UA gives only what it misses. `WalletLocked`; `Argument` (a key other than a seed's UA key, a KEM
  /// key on a kind that holds none, a profile without a registry); `FeatureMissing` (`attrs.pqz_key` without feature
  /// `pqz`; a PQZ key on a kind that holds none is `Argument`); `GasAboveTxCap`.
  Future<List<ArcRegistryWrite>> prepareRegister({required Register req}) =>
      ScaasSdk.instance.api.scaasSdkAccountAccountPrepareRegister(
        that: this,
        req: req,
      );

  /// KEM key rotation (owner 2026-11-22): the `setKemKey(ua, version, kem, sig)` that stores `key`'s KEM key of version
  /// `version` ≥ 1 ([`set_kem_key_args`]), quoted and landed by its record (`kemKeyAt(ua, version)` non-empty) as every
  /// registry write; `None` when that version is already stored. An unregistered UA: `Argument` (the registry refuses it).
  /// No PqVault name: any app core wraps to the new version once it lands (`kemKeyOf` follows the highest).
  Future<ArcRegistryWrite?> prepareSetKemKey({
    required KeyRef key,
    required String chain,
    required BigInt version,
    required KeyRef payer,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSetKemKey(
    that: this,
    key: key,
    chain: chain,
    version: version,
    payer: payer,
  );

  /// `AddKey` (CTR-ACC-10): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareSmartAddKey({
    required SmartOp op,
    required SubjectKeyArgs key,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSmartAddKey(
    that: this,
    op: op,
    key: key,
  );

  /// `CancelNonce` of lane `lane` (decimal) on the account.
  Future<ArcPrepared> prepareSmartCancelNonce({
    required SmartOp op,
    required String lane,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSmartCancelNonce(
    that: this,
    op: op,
    lane: lane,
  );

  /// `CancelRecovery` of the pending recovery.
  Future<ArcPrepared> prepareSmartCancelRecovery({required SmartOp op}) =>
      ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSmartCancelRecovery(
        that: this,
        op: op,
      );

  /// The deploy of the `SmartKeyAccount` of `first_key` and `guardian` (the zero address: none) by `factory`'s
  /// `deploy(firstKey, guardian)` (CTR-ACC-01), at [`smart_account_address`]'s address: a native send of `key` (an EVM key)
  /// quoted for review; `Wallet::submit_native_send` sends it. Errors as `Wallet::prepare_native_send` (a reverting call:
  /// its simulation's error).
  Future<NativeQuote> prepareSmartDeploy({
    required KeyRef key,
    required String chain,
    required String factory_,
    required SubjectKeyArgs firstKey,
    required String guardian,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSmartDeploy(
    that: this,
    key: key,
    chain: chain,
    factory_: factory_,
    firstKey: firstKey,
    guardian: guardian,
  );

  /// `Execute`: a decoded call (spec §13.2), or an opaque one only under [`AllowOpaqueCall`] (`OpaqueCallRefused`
  /// otherwise), its review flagged `opaque`.
  Future<ArcPrepared> prepareSmartExecute({
    required SmartOp op,
    required SmartCall call,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSmartExecute(
    that: this,
    op: op,
    call: call,
  );

  /// `RemoveKey` of the key at `index` (decimal).
  Future<ArcPrepared> prepareSmartRemoveKey({
    required SmartOp op,
    required String index,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSmartRemoveKey(
    that: this,
    op: op,
    index: index,
  );

  /// `RotateKey`: `key` added, the key at `index` removed, atomically.
  Future<ArcPrepared> prepareSmartRotateKey({
    required SmartOp op,
    required String index,
    required SubjectKeyArgs key,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSmartRotateKey(
    that: this,
    op: op,
    index: index,
    key: key,
  );

  /// `SetGuardian` (`0x` + 40 hex; zero: none); it also cancels the old guardian's pending recovery.
  Future<ArcPrepared> prepareSmartSetGuardian({
    required SmartOp op,
    required String guardian,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSmartSetGuardian(
    that: this,
    op: op,
    guardian: guardian,
  );

  /// The sender's side (spec §7.1): every check of the module doc on `blob` before anything is sent, then the registry
  /// writes `payer` (a native `evm` key) pays for: the registration (split as `prepare_register`'s), then `setKemKey` when
  /// the KEM key is committed and not yet stored; none for a UA registered with its KEM key. Quote, submit and follow each
  /// as `prepare_register`'s; prepare the payment only after the last one's `Landed`. `Argument` (another version, an
  /// entry other than `register` / `registerWebAuthn`, a field that does not decode), `RegistrationUaMismatch`,
  /// `RegistrationKindDisabled`, `RegistrationPopInvalid`, `RegistrationKemMissing`, `GasAboveTxCap`.
  Future<List<ArcRegistryWrite>> prepareSubmitRegistration({
    required RegistrationBlob blob,
    required String chain,
    required String expectedUa,
    required KeyRef payer,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountPrepareSubmitRegistration(
    that: this,
    blob: blob,
    chain: chain,
    expectedUa: expectedUa,
    payer: payer,
  );

  /// `updateMsig` (CTR-UA-44): the stored structure, version and bits read from the registry, the update planned by
  /// `scaas-ua` (`plan_msig_update`: version = stored + 1, the target's own refusals, `Ua(KeyData)`; its warnings returned),
  /// signed by `req.slots` of the stored structure (enabled and accepted, minimal) over typed `UAMsigUpdate` for this one
  /// registry and chain; landed when the registry's version reaches it.
  Future<MsigUpdatePlan> prepareUpdateMsig({required UpdateMsig req}) =>
      ScaasSdk.instance.api.scaasSdkAccountAccountPrepareUpdateMsig(
        that: this,
        req: req,
      );

  /// The quote of `write` by its payer (spec §13.3): its gas (controller call, owner auto-run 2026-11-19: where the gas table
  /// has the write's rows, the regular bound the table's and the gas limit max(the estimate of its calldata, the table's);
  /// else the estimate, whole), the chain's and the SDK's caps (a registration step also half the block gas limit, owner
  /// 2026-11-20), the payer's nonce. Quote a later step only after the one before it landed (its estimate reverts before).
  /// `PreparedUnknown`, `GasAboveTxCap`, `GasAboveBlockShare`, `GasCountUnknown` (an `msig` above the counts measured),
  /// `FeeAboveCap`.
  Future<SubmitQuote> quoteRegistryWrite({required ArcRegistryWrite write}) =>
      ScaasSdk.instance.api.scaasSdkAccountAccountQuoteRegistryWrite(
        that: this,
        write: write,
      );

  /// The registry a registration of `kind` on chain `chain` goes to (§12): `kindHome(kind)` of the profile's registry,
  /// which must be that registry; `RegistrationVerifyOnly` where it carries the kind verify-only (the home is another
  /// generation), `RegistrationKindDisabled` where no generation registers it.
  Future<String> registerTarget({required String chain, required int kind}) =>
      ScaasSdk.instance.api.scaasSdkAccountAccountRegisterTarget(
        that: this,
        chain: chain,
        kind: kind,
      );

  /// The receiver's blob (spec §7.1): the registration of `key` (a seed's UA key) as `prepare_register` builds it, named,
  /// with no secret. `WalletLocked`; `Argument` and `FeatureMissing` as `prepare_register`.
  Future<RegistrationBlob> registrationBlob({
    required KeyRef key,
    required RegisterAttrs attrs,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountRegistrationBlob(
    that: this,
    key: key,
    attrs: attrs,
  );

  /// The registration of `ua` (`0x` + 64 hex) on `chain` as the registry holds it now.
  Future<RegistrationState> registrationOf({
    required String chain,
    required String ua,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountRegistrationOf(
    that: this,
    chain: chain,
    ua: ua,
  );

  /// The gap scan (spec §7): returns the rows added (a registered UA already in the list is not added twice).
  /// `ChainUnknown`: no such profile; `Argument`: a profile with no registry or chain id, `gap` 0 or above 1024.
  Future<List<AccountInfo>> restore({required Restore req}) =>
      ScaasSdk.instance.api.scaasSdkAccountAccountRestore(that: this, req: req);

  /// Whether row `id` of seed `seed` holds a key the SDK signs with (a UA, native or key row); a watch row signs nothing.
  /// `Argument`: no such row.
  Future<bool> signs({required String seed, required String id}) => ScaasSdk
      .instance
      .api
      .scaasSdkAccountAccountSigns(that: this, seed: seed, id: id);

  /// Signs the payer's transaction carrying exactly `write`, writes the operation's row, returns its id; the send runs on
  /// and reports as `Event::OpState`; `Op::state` follows it to `Landed` by the record. `PreparedUnknown` (a write not of
  /// this SDK, or submitted already), `Argument` (a quote of another payer), `FeeAboveCap`; a failed signing of the payer's
  /// transaction (`WalletLocked`, …) leaves the write in the table, submittable again.
  Future<String> submitRegistryWrite({
    required ArcRegistryWrite write,
    required SubmitQuote quote,
  }) => ScaasSdk.instance.api.scaasSdkAccountAccountSubmitRegistryWrite(
    that: this,
    write: write,
    quote: quote,
  );

  /// Where UA `ua` (`0x` + 64 hex) lives on chain `chain`'s line: one `holderOf(ua)` on the profile's registry (§11.1); the
  /// record is read at [`UaLine::holder`], a key write goes there ([`UaLine::key_target`]), the PQZ attachment is read and
  /// written at its home ([`UaLine::pqz_target`]). `UaUnregistered` where no generation holds it; `Argument` without a
  /// registry or for a malformed id.
  Future<UaLine> uaLine({required String chain, required String ua}) => ScaasSdk
      .instance
      .api
      .scaasSdkAccountAccountUaLine(that: this, chain: chain, ua: ua);
}

