@sealed
class VaultImpl extends RustOpaque implements Vault {
  // Not to be used by end users
  VaultImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  VaultImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        ScaasSdk.instance.api.rust_arc_increment_strong_count_Vault,
    rustArcDecrementStrongCount:
        ScaasSdk.instance.api.rust_arc_decrement_strong_count_Vault,
    rustArcDecrementStrongCountPtr:
        ScaasSdk.instance.api.rust_arc_decrement_strong_count_VaultPtr,
  );

  /// A new vault passphrase for every vault of the seed: the pin envelope re-wrapped, the data key kept (CLI-UAL-19), so the PRF
  /// envelope still opens. `VaultOpen` for a wrong old one, `VaultPassphraseWeak` for a new one under vault v1's rule.
  Future<void> changePassphrase({
    required String seed,
    required ArcSecretBytes old,
    required ArcSecretBytes new_,
  }) => ScaasSdk.instance.api.scaasSdkVaultSeedsVaultChangePassphrase(
    that: this,
    seed: seed,
    old: old,
    new_: new_,
  );

  /// Marks the seed's backup `verified` after the three-word check passed (the seed unlocked: the MAC is rewritten).
  Future<void> confirmBackup({required String seed}) => ScaasSdk.instance.api
      .scaasSdkVaultSeedsVaultConfirmBackup(that: this, seed: seed);

  /// A BIP-85 child of the parent's main set (spec §6.4): 24 words at the parent's high-water mark `bip85Next`, raised and
  /// persisted in the parent's manifest (re-sealed under its same DEK) with the child's entry in one write; `class` and
  /// `warnings` inherited, `backup: pending`; the parent unlocked (`WalletLocked`), `SeedExists` (the index used up all the same:
  /// the raised mark is written), `LabelTaken`.
  Future<NewSeed> deriveChild({required DeriveChild req}) => ScaasSdk
      .instance
      .api
      .scaasSdkVaultSeedsVaultDeriveChild(that: this, req: req);

  /// Root (d)'s new seed set (spec §6.6): a secp256k1 EVM key only. `Argument` (another network, not 32 bytes, outside
  /// [1, n)), `DerivationPassphraseShort`, `VaultPassphraseWeak`, `SeedExists`, `LabelTaken`.
  Future<NewSeed> deriveFromKey({required DeriveFromKey req}) => ScaasSdk
      .instance
      .api
      .scaasSdkVaultSeedsVaultDeriveFromKey(that: this, req: req);

  /// Root (c)'s new seed set (spec §6.6). `OriginSignature` (the signatures differ, a wrong length, `r` / `s` / `v` out of
  /// range, recovering to another address), `DerivationPassphraseShort`, `VaultPassphraseWeak`, `SeedExists`, `LabelTaken`.
  Future<NewSeed> deriveFromSignature({required DeriveFromSignature req}) =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultDeriveFromSignature(
        that: this,
        req: req,
      );

  /// Drops the PRF envelope of every vault of the seed (the passphrase still opens; an earlier copy keeps its envelope). The
  /// seed must be unlocked (`WalletLocked`): the index MAC covers the vault texts (T13b ruling 3), so its wallet rewrites it;
  /// then the seed is locked (its wallet holds the old envelopes, which a later re-seal would write back).
  Future<void> disablePrfUnlock({required String seed}) => ScaasSdk.instance.api
      .scaasSdkVaultSeedsVaultDisablePrfUnlock(that: this, seed: seed);

  /// Adds a passkey PRF envelope to every vault of the seed (one credential, one fresh per-seed salt, one assertion),
  /// opened by the vault passphrase once. `AuthenticatorRefused` for no authenticator, no RP ID, an answer without a PRF
  /// output or an output the app never wrote (nothing written to the keystore).
  Future<void> enablePasskeyUnlock({
    required String seed,
    required ArcSecretBytes vaultPassphrase,
  }) => ScaasSdk.instance.api.scaasSdkVaultSeedsVaultEnablePasskeyUnlock(
    that: this,
    seed: seed,
    vaultPassphrase: vaultPassphrase,
  );

  /// Adds a platform-secret envelope (a Keychain / Android Keystore key under `policy`, research decision 8) to every vault of
  /// the seed, opened by the vault passphrase once. `AuthenticatorRefused` for a refusal or a secret the app never wrote.
  Future<void> enablePlatformUnlock({
    required String seed,
    required ArcSecretBytes vaultPassphrase,
    required KeyPolicy policy,
  }) => ScaasSdk.instance.api.scaasSdkVaultSeedsVaultEnablePlatformUnlock(
    that: this,
    seed: seed,
    vaultPassphrase: vaultPassphrase,
    policy: policy,
  );

  /// A new 24-word seed (spec §6.4): 32 bytes of the OS generator inside `scaas-ua`, its seed and manifest vaults sealed
  /// under the vault passphrase, its entry written with `backup: pending` before the backup is handed out. `Argument` for a
  /// label outside its rule, `LabelTaken`, `VaultPassphraseWeak`; the store's errors as `VaultIo` / `StoreConflict`.
  Future<NewSeed> generate({required Generate req}) => ScaasSdk.instance.api
      .scaasSdkVaultSeedsVaultGenerate(that: this, req: req);

  /// Imports a classical key as a leaf of the seed's main set (spec §6.7) through `ua-rs` `import_native_key` (tagged with its
  /// network, refused for another, CLI-SGN-11; the networks without import refuse it: `Argument`). The seed must be unlocked
  /// (`WalletLocked`); `vault_passphrase` must open the seed's own `seed` vault (`VaultOpen` otherwise: every vault of a seed
  /// opens with one passphrase). The new vault, the re-sealed manifest (same DEK, its envelopes kept), the warning
  /// `imported_key` and the rewritten MAC go in one write, refused `StoreConflict` when the stored seed moved since it was read
  /// (its label taken, its manifest another: a second SDK on the same store). Any failure after the open wallet took the key
  /// locks the seed, so no later re-seal writes a manifest that lists an import with no vault (closing review P2-7).
  Future<ImportedKey> importKey({required ImportKey req}) => ScaasSdk
      .instance
      .api
      .scaasSdkVaultSeedsVaultImportKey(that: this, req: req);

  /// Imports 12 to 24 English words (spec §6.4): checksum checked (`MnemonicInvalid`), 12 to 21 words with `short_seed`,
  /// `backup: verified`; `SeedExists` when its fingerprint is held, `LabelTaken`, `VaultPassphraseWeak`.
  Future<SeedInfo> importWords({required ImportWords req}) => ScaasSdk
      .instance
      .api
      .scaasSdkVaultSeedsVaultImportWords(that: this, req: req);

  /// Root (c)'s typed data for `account` and seed-set number `set`, as the JSON an EIP-712 wallet signs
  /// (`eth_signTypedData_v4`): built by `scaas-ua`, never by the app. `Argument` for a malformed account.
  Future<String> keyDerivationTypedData({
    required String accountHex,
    required int set_,
  }) => ScaasSdk.instance.api.scaasSdkVaultSeedsVaultKeyDerivationTypedData(
    that: this,
    accountHex: accountHex,
    set_: set_,
  );

  /// Whether the stored keystore is older than its anchor (an earlier copy put back, spec §6.3): an app checks it after
  /// `Sdk::open`, where no subscriber can see the event yet; every later read emits `Event::KeystoreRollback` while it holds.
  Future<bool> keystoreRollback() =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultKeystoreRollback(that: this);

  /// Locks the seed (and its hidden sets): every handle revoked, new calls refused at once; the hidden sets' operations not yet
  /// terminal come back (none are followed in memory before plan T10).
  Future<List<String>> lock({required String seed}) =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultLock(that: this, seed: seed);

  /// Locks every seed.
  Future<List<String>> lockAll() =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultLockAll(that: this);

  /// The memory protection of an unlocked seed's key arena now (`mlock`, no-dump; best effort, closing review P3): an app can
  /// tell whether the retained PRF key and the opened keys are locked in RAM. `WalletLocked` for a locked seed.
  Future<MemoryProtection> memoryProtection({required String seed}) => ScaasSdk
      .instance
      .api
      .scaasSdkVaultSeedsVaultMemoryProtection(that: this, seed: seed);

  /// Opens a hidden set of the seed (spec §6.5): a second wallet of the same vault under `bip39_passphrase`, with its own random
  /// id; nothing written, no event, no row. A wrong BIP-39 passphrase is not an error (other addresses).
  Future<SessionSet> openHidden({
    required String seed,
    required Unlock unlock,
    required ArcSecretBytes bip39Passphrase,
  }) => ScaasSdk.instance.api.scaasSdkVaultSeedsVaultOpenHidden(
    that: this,
    seed: seed,
    unlock: unlock,
    bip39Passphrase: bip39Passphrase,
  );

  /// Removes the seed: locks it and drops its entry (the previous container stays as `keystore.prev`). A seed whose backup
  /// is `pending` needs `ConfirmRemoveUnbacked` too (`ConfirmationMissing`). No unlock needed.
  Future<void> remove({required Remove req}) =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultRemove(that: this, req: req);

  /// Renames the seed (unlocked: the MAC is rewritten); `LabelTaken`, `Argument` for a label outside its rule.
  Future<void> rename({required String seed, required String label}) => ScaasSdk
      .instance
      .api
      .scaasSdkVaultSeedsVaultRename(that: this, seed: seed, label: label);

  /// The seed's info as listed now.
  Future<SeedInfo> seed({required String seed}) =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultSeed(that: this, seed: seed);

  /// The seeds of the keystore, in display order.
  Future<List<SeedInfo>> seeds() =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultSeeds(that: this);

  /// A 64-byte EIP-2098 compact signature as the 65-byte `r ‖ s ‖ v` root (c) takes: the explicit conversion
  /// (`OriginSignature` for another length).
  Future<ArcSecretBytes> signatureFromCompact({required ArcSecretBytes sig}) =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultSignatureFromCompact(
        that: this,
        sig: sig,
      );

  /// Unlocks the seed by its vault passphrase (every vault opened now, the passphrase not kept) or by its passkey / platform
  /// PRF envelope (the seed and manifest vaults opened, the PRF key kept for the others' first use; spec §6.10, owner
  /// 2026-11-18): `VaultOpen` for a wrong secret, `AuthenticatorRefused` (no authenticator, no envelope, no PRF output),
  /// `KeystoreMismatch` when the index MAC does not verify (the seed stays locked, the event says so), `SeedUnknown`. A seed
  /// already open stays as it is (`Ok`, nothing asked): one session per seed.
  Future<void> unlock({required String seed, required Unlock unlock}) =>
      ScaasSdk.instance.api.scaasSdkVaultSeedsVaultUnlock(
        that: this,
        seed: seed,
        unlock: unlock,
      );

  /// Whether `word` (one word, as a secret) is on the BIP-39 English list; the list never leaves `scaas-ua` (R17).
  Future<bool> wordInList({required ArcSecretBytes word}) => ScaasSdk
      .instance
      .api
      .scaasSdkVaultSeedsVaultWordInList(that: this, word: word);
}

@sealed
class WalletImpl extends RustOpaque implements Wallet {
  // Not to be used by end users
  WalletImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  WalletImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        ScaasSdk.instance.api.rust_arc_increment_strong_count_Wallet,
    rustArcDecrementStrongCount:
        ScaasSdk.instance.api.rust_arc_decrement_strong_count_Wallet,
    rustArcDecrementStrongCountPtr:
        ScaasSdk.instance.api.rust_arc_decrement_strong_count_WalletPtr,
  );

  /// The balances of `id` on `chain` at one block. EVM: `id` a `0x` 20-byte address or a `0x` 32-byte UA; another family
  /// (spec §8.7): the family's printed form, or a `0x` 32-byte UA id where the family keeps a UA ledger, read at one final
  /// height. `ChainUnknown`, `ProfileMismatch` (a listed token's `chainUid()`), `Argument` (an id of another form),
  /// `FeatureMissing` (a family this build does not read).
  Future<Balances> balances({required String id, required String chain}) =>
      ScaasSdk.instance.api.scaasSdkWalletWalletBalances(
        that: this,
        id: id,
        chain: chain,
      );

  /// The history of `account` (a `0x` 20-byte address or a `0x` 32-byte UA) on `chain`: one span window per call, at or
  /// below the profile's final block, strictly older than `before`, at most `limit` items, newest first. Writes nothing (no
  /// cursor: a hidden set's account may be read). `ChainUnknown`, `ProfileMismatch`, `Argument` (`limit` 0, a bad id).
  Future<HistoryPage> history({
    required String account,
    required String chain,
    Cursor? before,
    required int limit,
  }) => ScaasSdk.instance.api.scaasSdkWalletWalletHistory(
    that: this,
    account: account,
    chain: chain,
    before: before,
    limit: limit,
  );

  /// The public key and address of a seed's native key (spec §8.5); `ss58_prefix` for a Polkadot key's SS58 form at another
  /// prefix. `WalletLocked`, `FeatureMissing`, `Argument`.
  Future<NativeAddress> nativeAddress({
    required NativeKeyRef key,
    int? ss58Prefix,
  }) => ScaasSdk.instance.api.scaasSdkWalletWalletNativeAddress(
    that: this,
    key: key,
    ss58Prefix: ss58Prefix,
  );

  ///Prepares `AddReserve` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareAddReserve({required AddReserve req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareAddReserve(that: this, req: req);

  ///Prepares `UABurn` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareBurn({required Burn req}) => ScaasSdk.instance.api
      .scaasSdkWalletWalletPrepareBurn(that: this, req: req);

  ///Prepares `UACancelNonce` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareCancelNonce({required CancelNonce req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareCancelNonce(that: this, req: req);

  ///Prepares `UADelegateRevoke` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareDelegateRevoke({required DelegateRevoke req}) =>
      ScaasSdk.instance.api.scaasSdkWalletWalletPrepareDelegateRevoke(
        that: this,
        req: req,
      );

  /// `UAExecute` on a mandate wallet: a decoded call (spec §13.2), or an opaque one only under [`AllowOpaqueCall`]
  /// (`OpaqueCallRefused` otherwise), its review flagged `opaque`.
  Future<ArcPrepared> prepareExecute({required Execute req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareExecute(that: this, req: req);

  /// Quotes a native send (spec §8.5): `TxTypeRefused` (a type other than 0, 1, 2; 2 on a chain without a base fee),
  /// `Argument` (chain id 0, a bad address, value or data, a key other than a native `evm` one), `GasAboveTxCap`,
  /// `FeeAboveCap`.
  Future<NativeQuote> prepareNativeSend({required NativeSend req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareNativeSend(that: this, req: req);

  /// `mtxPay` with `PayMeta` v3: the `entryRef` its `metaPayId`, the review listing `payNo` (as UUID text), `save`, the
  /// schema and the body.
  Future<ArcPrepared> preparePay({required Pay req}) => ScaasSdk.instance.api
      .scaasSdkWalletWalletPreparePay(that: this, req: req);

  /// `UAPayUnderMandate`: the delegate's payment from the mandate wallet `wallet`.
  Future<ArcPrepared> preparePayUnderMandate({required PayUnderMandate req}) =>
      ScaasSdk.instance.api.scaasSdkWalletWalletPreparePayUnderMandate(
        that: this,
        req: req,
      );

  /// `UAPayWithTax` (regulated kinds): the payment as a pay's, its tax; checked under `Expect::Op`.
  Future<ArcPrepared> preparePayWithTax({required PayWithTax req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPreparePayWithTax(that: this, req: req);

  /// `UAPayeeFee`: the payee signs its fee over the payment it expects, under `Expect::PayeeFee` (never the payment's
  /// check); the payer's signature and the `PayMeta` ride unsigned.
  Future<ArcPrepared> preparePayeeFee({required PayeeFee req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPreparePayeeFee(that: this, req: req);

  /// `UARelayFee`: a fee bound to the relayed call by its hash; the review lists the call's target and length.
  Future<ArcPrepared> prepareRelayFee({required RelayFee req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareRelayFee(that: this, req: req);

  ///Prepares `UARevokeMandate` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareRevokeMandate({required RevokeMandate req}) =>
      ScaasSdk.instance.api.scaasSdkWalletWalletPrepareRevokeMandate(
        that: this,
        req: req,
      );

  ///Prepares `UASetMandate` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareSetMandate({required SetMandate req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareSetMandate(that: this, req: req);

  ///Prepares `UASetPayee` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareSetPayee({required SetPayee req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareSetPayee(that: this, req: req);

  /// The transfer on ids (owner 2026-11-18, ruling 6): `UAMetaTransfer` sent as `mtxExecuteTransfer`, a gateway's
  /// `POST /v1/ua-metatx`.
  Future<ArcPrepared> prepareTransfer({required Transfer req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareTransfer(that: this, req: req);

  ///Prepares `UAUnwrap` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareUnwrap({required Unwrap req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareUnwrap(that: this, req: req);

  ///Prepares `UAUnwrapLeg` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareUnwrapLeg({required UnwrapLeg req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareUnwrapLeg(that: this, req: req);

  ///Prepares `UAUnwrapToUA` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareUnwrapToUa({required UnwrapToUa req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareUnwrapToUa(that: this, req: req);

  ///Prepares `Wrap` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareWrap({required Wrap req}) => ScaasSdk.instance.api
      .scaasSdkWalletWalletPrepareWrap(that: this, req: req);

  ///Prepares `WrapLeg` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareWrapLeg({required WrapLeg req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareWrapLeg(that: this, req: req);

  ///Prepares `WrapToUA` (spec §21): `ProfileMismatch`, `Argument`, `WalletLocked`.
  Future<ArcPrepared> prepareWrapToUa({required WrapToUa req}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletPrepareWrapToUa(that: this, req: req);

  /// Signs exactly `q`, writes the operation's row, returns its id; the send runs on and reports as `Event::OpState`, the
  /// state follows `tx_state` (`Op::state`).
  Future<String> submitNativeSend({required NativeQuote q}) => ScaasSdk
      .instance
      .api
      .scaasSdkWalletWalletSubmitNativeSend(that: this, q: q);

  /// The profile's tokens and, with `with_index`, every token of the factory's index (unlisted unless on the list), each read
  /// once per session. `ChainUnknown`; `ProfileMismatch`: a token's `chainUid()` is not the profile's; `Argument`: the
  /// index asked of a profile without a factory.
  Future<List<TokenInfo>> tokens({
    required String chain,
    required bool withIndex,
  }) => ScaasSdk.instance.api.scaasSdkWalletWalletTokens(
    that: this,
    chain: chain,
    withIndex: withIndex,
  );
}
